      ...parseParts(wrap(base), { split }).map((p) => ({ ...p, clip })),
      ...parseParts(wrap(badge), { split }).map((p) => ({ ...p, translate: [p.translate[0] + Number(x), p.translate[1] + Number(y)] })),
