  const paths = [...inner.matchAll(/<path\b([^>]*)\/>/g)];
  const leftover = inner.replace(/<path\b[^>]*\/>/g, '');
  if (!paths.length || leftover.trim()) throw new Error('Unsupported artwork: only paths, optionally in one translated group');
