  const parts = motion.parts ?? [];
  if (!Array.isArray(parts) || !parts.length) throw new Error(`${motion.type}: parts must list at least one part`);
  const dur = motion.dur ?? 1.6;
  if (!(dur > 0 && dur <= 60)) throw new Error('dur must be between 0 and 60 seconds');
  if (motion.ease !== undefined && !EASE_RE.test(String(motion.ease))) throw new Error(`Invalid easing: ${motion.ease}`);
  if (motion.origin !== undefined && !(Array.isArray(motion.origin) && motion.origin.length === 2)) throw new Error('origin must be [x, y]');
  const origin = motion.origin ?? [12, 12];
  const delay = motion.delay ?? 0;
